PR #644: Embargo badge + quick unpublish in the draft queue

Desk editors keep opening drafts just to check whether they are under embargo, and pulling a story that went out early takes four clicks.
This adds an embargo badge (amber outline, shows the lift time in the newsroom's timezone) and a one-click unpublish action on each queue row.
Unpublish still goes through the standard confirm dialog.

diff --git a/web/src/queue/DraftRow.tsx b/web/src/queue/DraftRow.tsx
index 6d1e0b4..b38f7c2 100644
--- a/web/src/queue/DraftRow.tsx
+++ b/web/src/queue/DraftRow.tsx
@@ -1,31 +1,55 @@
 import { Draft } from "../api/types";
 import { formatByline } from "../lib/format";
+import { formatInNewsroomTz } from "../lib/time";
+import { useConfirm } from "../ui/confirm";
+import { TrashIcon } from "../ui/icons";
 import styles from "./DraftRow.module.css";

 type Props = {
   draft: Draft;
   onOpen: (id: string) => void;
+  onUnpublish: (id: string) => Promise<void>;
 };

-export function DraftRow({ draft, onOpen }: Props) {
+export function DraftRow({ draft, onOpen, onUnpublish }: Props) {
+  const confirm = useConfirm();
+  const embargoed =
+    draft.embargoUntil !== null && new Date(draft.embargoUntil) > new Date();
+
+  async function handleUnpublish(e: React.MouseEvent) {
+    e.stopPropagation();
+    const ok = await confirm({
+      title: "Unpublish this story?",
+      body: `"${draft.headline}" will be removed from the site and returned to drafts.`,
+      confirmLabel: "Unpublish",
+      destructive: true,
+    });
+    if (ok) await onUnpublish(draft.id);
+  }
+
   return (
     <li className={styles.row}>
       <button className={styles.open} onClick={() => onOpen(draft.id)}>
         <span className={styles.headline}>{draft.headline}</span>
         <span className={styles.byline}>{formatByline(draft.authors)}</span>
       </button>
+      {embargoed && (
+        <span className={styles.embargo}>
+          Embargo until {formatInNewsroomTz(draft.embargoUntil!, "MMM d, HH:mm")}
+        </span>
+      )}
       <span className={styles.status} data-status={draft.status}>
         {draft.status}
       </span>
+      {draft.status === "published" && (
+        <span className={styles.unpublish} onClick={handleUnpublish}>
+          <TrashIcon aria-hidden="true" />
+        </span>
+      )}
     </li>
   );
 }
